// The words a gathered message is named by in the gathered line: its brief (options.brief), else its title. Pure.
function digestBrief(item) {
  const options = item[3] || {};
  return options.brief || splitMessage(options.literal ? String(item[0]) : translateMessage(item[0]))[0];
}
// The gathered line's description: each brief once, in the order they came, with how many - a brief that ends in a
// count ('새 핀 1', one per document) adds its count up ('새 핀 2'), any other counts how many said it ('나를 부름 2').
// Pure.
function digestLine(briefs) {
  const seen = new Map();
  briefs.forEach((brief) => {
    const match = /^(.*\S) (\d+)$/.exec(brief),
      name = match ? match[1] : brief,
      count = match ? +match[2] : 1,
      was = seen.get(name);
    seen.set(name, { n: (was ? was.n : 0) + count, counted: !!match || (was ? was.counted : false) });
  });
  return [...seen].map(([brief, tally]) => (tally.n > 1 || tally.counted ? brief + ' ' + tally.n : brief)).join(' · ');
}
function digestNote(title, items) {
  // this document's news first
  items = [...items.filter((item) => !(item[3] || {}).back), ...items.filter((item) => !!(item[3] || {}).back)];
  const dots = digestDots(items);
  const notice = lineNote(
    title + ' — ' + digestLine(items.map(digestBrief)),
    NOTICE_KIND.INFO,
    {
      label: '펼치기',
      tip: '모은 소식을 하나씩 상태 줄에 놓습니다',
      fn: () => {
        const all = notice ? notice.items || [] : [];
        all.forEach((item) => digestReplay(item, false));
        if (all.length > 1 && !$('#status-list').open) noticeStatusLine().toggleList();
      },
    },
    {
      literal: true,
      keep: true,
      back: true,
      dots,
      digest: false,
      onEnd: (acted, seen) => {
        if (!acted && notice) digestClosed(notice.items || [], seen);
      },
    },
  );
  if (notice) {
    notice.items = items;
    notice.digestTitle = title;
  }
}
// A gathered line went other than by [펼치기] (its [x]: seen): the groups it held end with it - each of their messages
// has gone, so what a group's end checks (no other new-pins message, documents/flow-updates.ts) sees them gone - and
// then what each held for its end runs, as seen.
function digestClosed(items, seen) {
  items.forEach((item) => {
    const group = (item[3] || {}).group,
      entry = group ? GROUPS.get(group) : undefined;
    if (entry && group && !(entry.n && NOTICES.has(entry.n.n))) GROUPS.delete(group);
  });
  items.forEach((item) => {
    const ended = (item[3] || {}).onEnd;
    if (ended) ended(false, seen);
  });
}
// Puts a gathered message on the line as it would have come - behind what the line says (back), or, unfolded by
// [펼치기], in front; a group's message is that group's again.
function digestReplay(item, back) {
  const options = item[3] || {},
    notice = lineNote(item[0], item[1], item[2], { ...options, digest: false, back: back || !!options.back });
  const entry = options.group && GROUPS.get(options.group);
  if (entry && notice) entry.n = notice;
}
// Takes group's gathered message out of a gathered line not yet unfolded, so the group's new event merges into it and
// is said on its own (groupNote); the line says what is left. Whether there was one.
function digestTake(group) {
  for (const notice of NOTICES.values()) {
    const items = notice.items;
    if (!items) continue;
    const index = items.findIndex((item) => (item[3] || {}).group === group);
    if (index < 0) continue;
    items.splice(index, 1);
    digestRetitle(notice);
    return true;
  }
  return false;
}
// The chips the gathered messages mark (digestNote's dots): each one's dot once. Pure but for the panel's open state.
function digestDots(items) {
  return [
    ...new Set(items.map((item) => noticeDot((item[3] || {}).dot || '', noticePanel().sideOpen())).filter(Boolean)),
  ];
}
// A gathered line says what it holds now (digestTake, foldedLess, foldedGone): each brief once with how many, and the
// dots of those alone - one left stays a gathered line naming it - or, holding nothing more, it goes (nothing it held
// runs for its end: what took them out did).
function digestRetitle(notice) {
  const items = notice.items || [];
  if (!items.length) {
    notice.onEnd = null;
    endNotice(notice, true);
    return;
  }
  notice.dots = digestDots(items);
  const [title, description] = splitMessage(
    (notice.digestTitle || notice.title) + ' — ' + digestLine(items.map(digestBrief)),
  );
  notice.title = title;
  notice.desc = description;
  noticeStatusLine().setSignature('');
  noticeStatusLine().draw();
}

// A CLICK message - a passing notice that is not an undo (a restored draft's [버리기]) - lasts until the next press
// somewhere else: a click (a tap, Enter on a button) outside it ends it; a scroll does not. The press that made it has
// passed by the time it exists. An undo is never CLICK (rule 2).
document.addEventListener(
  'click',
  (event) => {
    const target = event.target instanceof Node ? event.target : null;
    NOTICES.forEach((notice) => {
      if (notice.life !== NOTICE_LIFE.CLICK) return;
      const own =
        notice.place === NOTICE_PLACE.LINE
          ? !!(target instanceof Element && target.closest('#status,#status-list'))
          : !!(notice.el && notice.el.contains(target));
      if (!own) endNotice(notice, false);
    });
  },
  true,
);

// One message's element, made once and kept on n.el (a redraw moves it, so a focus inside survives and an alert is not
// read out again): status icon, title and description (already in the UI language, so translate="no"), its action, and
// [x] - none on a chip, which goes by itself. ERR and WARN banners are alerts. A TIMER message holds while a mouse is
// on it - from a real movement over it (realMove), not from being drawn under a resting pointer - until the pointer
// leaves (armNotice).
function noticeElement(notice, className) {
  if (notice.el) return notice.el;
  const element = document.createElement('div');
  element.className = 'nt ' + className + ' nk-' + notice.kind;
  element.dataset.n = String(notice.n);
  if (notice.place === NOTICE_PLACE.BANNER && (notice.kind === NOTICE_KIND.ERR || notice.kind === NOTICE_KIND.WARN))
    element.setAttribute('role', 'alert');
  const chip = notice.place === NOTICE_PLACE.CHIP,
    title = chip && notice.label ? notice.label : notice.title,
    description = chip ? '' : notice.desc;
  setHtml(
    element,
    html`<span class="nt-ic">${noticeIcon(notice.kind)}</span><span class="nt-t" translate="no"><span class="nt-ti">${title}</span>${description ? html`<span class="nt-d">${description}</span>` : ''}</span><span class="nt-acts">${noticeButtons(notice, !chip)}</span>`,
  );
  if (chip)
    for (const eventType of ['pointerdown', 'mousedown'])
      // a press on the chip never starts a selection on the page under it
      element.addEventListener(eventType, (event) => event.stopPropagation());
  if (notice.life === NOTICE_LIFE.TIMER) {
    element.addEventListener(
      'pointermove',
      (event) => {
        if (!notice.hover && realMove(event) && NOTICES.has(notice.n)) {
          notice.hover = true;
          armNotice(notice);
        }
      },
      { passive: true },
    );
    for (const eventType of ['pointerleave', 'pointercancel'])
      element.addEventListener(eventType, () => {
        if (notice.hover && NOTICES.has(notice.n)) {
          notice.hover = false;
          armNotice(notice);
        }
      });
  }
  notice.el = element;
  return element;
}
// A message's buttons: its action (with its description, if any; aria-busy while its request is out) and, with close,
// [x] named '알림 닫기'.
function noticeButtons(notice, close) {
  const action = notice.act,
    tip = action && action.tip ? html` data-tip="${action.tip}"` : '',
    busy = notice.busy ? html` aria-busy="true"` : '';
  return html`${action ? html`<button type="button" class="btn-sm btn-secondary nt-act" data-act="notice-act" data-n="${notice.n}"${tip}${busy}><span class="lbl">${translate(action.label)}</span></button>` : ''}\
${close ? html`<button type="button" class="btn-icon btn-sm btn-ghost nt-x" data-act="notice-x" data-n="${notice.n}" aria-label="알림 닫기">${lucideIcon('x')}</button>` : ''}`;
}

// The focused element inside a drawn message, if any: a redraw that detaches it gives the focus back (noticeRefocus).
function noticeFocus() {
  const active = focusedElement();
  return active && active.closest('.nt') ? active : null;
}
function noticeRefocus(focused) {
  if (focused && document.contains(focused) && document.activeElement !== focused)
    focused.focus({ preventScroll: true });
}

// Banners in their hosts: the composer's above its save row, the review section's under its head (at the top of the
// list while that section is hidden), the Trash's above its list, the list's at its top. One already in place is not
// moved.
function drawBanners() {
  const focused = noticeFocus();
  BANNERS.forEach((notice, host) => {
    const element = noticeElement(notice, 'nt-banner'),
      inReview = host === NOTICE_HOST.REVIEW && !$('#sec-review').hidden;
    const parent =
      host === NOTICE_HOST.COMPOSER
        ? $('#c-actions')
        : host === NOTICE_HOST.TRASH
          ? $('#trash')
          : inReview
            ? $('#sec-review')
            : $('#list');
    const before =
      host === NOTICE_HOST.TRASH ? $('#trash-list') : inReview ? $('#review-pins') : parent.firstElementChild;
    if (element.parentNode !== parent || (before !== element && element.nextElementSibling !== before))
      parent.insertBefore(element, before === element ? element.nextElementSibling : before);
  });
  noticeRefocus(focused);
  syncSaveButton();
  tipFollow();
} // a banner moved (the review section hid: to the list's top) keeps its focus; what is under a banner moved down
// The composer's [핀 저장] reads [다시 저장] while its banner is a failed save (saveButtonLabel), and goes back after.
function syncSaveButton() {
  const button = $('#btn-save');
  if (!button || button.dataset.pending) return;
  const banner = BANNERS.get(NOTICE_HOST.COMPOSER),
    retry = !!(banner && banner.save);
  if ((button.dataset.retry === '1') !== retry) {
    if (retry) button.dataset.retry = '1';
    else delete button.dataset.retry;
    setHtml(button, noticeComposer().saveButtonLabel());
  }
}
// A composer's banner belongs to its selection: when the composer closes (saved, cancelled), it goes with it.
new MutationObserver(() => {
  if ($('#composer').hidden) {
    const notice = BANNERS.get(NOTICE_HOST.COMPOSER);
    if (notice) endNotice(notice, false);
  }
}).observe($('#composer'), { attributes: true, attributeFilter: ['hidden'] });

// Rows in a card's place and notes in a card, after drawPins drew the list. A row waits until its card has left the
// section (away), then goes into the slot the list drew where its pin would stand in the list's order (cardRows: under
// its day line), or for a row made after that draw where placeRow puts it; once its pin is back in that section, what
// it offers to undo is undone and it goes - unless it holds a deferred send, whose card stays out until the send. A
// note goes above its card's buttons (or a done pin's row's end); a note whose card is not drawn moves to the status
// line (offerToLine). focus = what noticeFocus() saw before the redraw.
function drawOffers(focus) {
  NOTICES.forEach((notice) => {
    if (notice.place === NOTICE_PLACE.ROW) {
      const box = notice.sec === 'review' ? $('#review-pins') : $('#pins');
      if (box.querySelector('.pin.card[data-id="' + notice.pin + '"]')) {
        if (notice.away && !notice.gone) endNotice(notice, true);
        else if (notice.el) notice.el.remove();
        return;
      }
      notice.away = true;
      // its last card may just have left (drawPins keeps it shown too)
      if (notice.sec === 'review') $('#sec-review').hidden = false;
      const element = noticeElement(notice, 'nt-row'),
        slot = box.querySelector('.nt-slot[data-slot="' + notice.n + '"]');
      if (slot) slot.replaceWith(element);
      else if (element.parentElement !== box) noticePanel().placeRow(box, notice, element);
    } // one standing since the last draw has its place
    else if (notice.place === NOTICE_PLACE.CARD) {
      const card = document.querySelector(
        '#list .pin.card[data-id="' + notice.pin + '"],#list .arc-row[data-id="' + notice.pin + '"]',
      );
      if (!card) {
        offerToLine(notice);
        return;
      }
      const element = noticeElement(notice, 'nt-note'),
        actions = card.querySelector(':scope>.acts');
      if (actions) actions.before(element);
      else card.appendChild(element);
    }
  });
  noticeRefocus(focus || null);
}

// Chips on marks, after marks() drew them: on the pin's mark, kept on its page. A chip whose mark is not drawn (another
// document, a failed reload) moves to the status line - unless it waits for its first reload (pending) - and so does
// one that would sit under the select mode's bar (chipsClearOfBar).
function drawChips() {
  NOTICES.forEach((notice) => {
    if (notice.place !== NOTICE_PLACE.CHIP) return;
    const anchor =
      findMaybe(document, '.mark[data-pin="' + notice.pin + '"]', HTMLElement) ||
      // a page verdict line shows its pin instead of a mark
      findMaybe(document, '#doc .pv[data-pin="' + notice.pin + '"]', HTMLElement);
    if (!anchor) {
      if (!notice.pending) offerToLine(notice);
      return;
    }
    const focused = noticeFocus(),
      element = noticeElement(notice, 'nt-chip');
    if (element.parentNode !== anchor) anchor.appendChild(element);
    element.style.left = '';
    element.style.right = '';
    element.style.maxWidth = '';
    chipInRoom(element, anchor);
    noticeRefocus(focused);
  });
  chipsClearOfBar();
}
// Keeps a chip where it can be pressed: inside its page, inside what the PDF area shows, and clear of a panel laid over
// the PDF area (the unfolded foldable's overlay panel while composing). Where the room is narrower than the chip its
// words give way (ellipsis, .nt-t) - never its [되돌리기] - then it moves left until it fits. A page verdict line's
// chip stands in the line's row (notices.css), which already keeps out of all of that (sizePageLines): nothing to move.
function chipInRoom(chip, anchor) {
  if (anchor.classList.contains('pv')) return;
  const scroller = $('#left'),
    panel = $('#right'),
    box = (anchor.closest('.pg') || anchor).getBoundingClientRect(),
    scrollerRect = scroller.getBoundingClientRect();
  let right = Math.min(box.right, scrollerRect.left + scroller.clientWidth) - 4;
  const left = Math.max(box.left, scrollerRect.left) + 4,
    firstRect = chip.getBoundingClientRect();
  // A panel beside or over the PDF area - a column down its right side, not a bottom sheet (which starts at its left) -
  // bounds the chip at every height: the chip may be scrolled up beside it after it is drawn.
  if (panel && panel.getClientRects().length) {
    const panelRect = panel.getBoundingClientRect();
    if (panelRect.left > scrollerRect.left + 40) right = Math.min(right, panelRect.left - 4);
  }
  // ...and so does the panel's handle (#grip), whose touch area (::after, 44px on touch) reaches into the PDF area at
  // the panel's middle: a chip scrolled there had its [되돌리기] under the handle.
  const grip = $('#grip');
  if (grip && grip.getClientRects().length) {
    const gripRect = grip.getBoundingClientRect(),
      reach = Math.max(gripRect.width, parseFloat(getComputedStyle(grip, '::after').width) || 0);
    if (gripRect.left > scrollerRect.left + 40) right = Math.min(right, gripRect.right - reach - 4);
  }
  if (right - left <= 0) return;
  if (firstRect.width > right - left) chip.style.maxWidth = Math.floor(right - left) + 'px';
  const chipRect = chip.getBoundingClientRect(),
    over = chipRect.right - right,
    under = left - chipRect.left;
  if (over > 0) chip.style.left = Math.round(chip.offsetLeft - Math.min(over, chipRect.left - left)) + 'px';
  else if (under > 0) chip.style.left = Math.round(chip.offsetLeft + under) + 'px';
}
// Whether two boxes (left, top, right, bottom) overlap by more than a touching edge. Pure.
function boxesMeet(
  first,
  second,
) {
  return (
    first.left < second.right && second.left < first.right && first.top < second.bottom && second.top < first.bottom
  );
}
// A chip never sits under the select mode's bar (#sel-bar, over the top of the PDF area while the mode is on): one
// whose box meets the bar's - the mode turned on, or the page scrolled the mark up under it - takes its undo to the
// status line. Nothing is read while no chip is up, and while the area scrolls only once a frame (with placeChips):
// read on every scroll event it forced a layout each time - seconds of long tasks over a first scroll through a list of
// a hundred pins.
function chipsClearOfBar() {
  let any = false;
  NOTICES.forEach((notice) => {
    if (notice.place === NOTICE_PLACE.CHIP && notice.el) any = true;
  });
  if (!any) return;
  const bar = $('#sel-bar');
  if (!bar || !bar.getClientRects().length) return;
  const barRect = bar.getBoundingClientRect();
  NOTICES.forEach((notice) => {
    if (
      notice.place === NOTICE_PLACE.CHIP &&
      notice.el &&
      notice.el.getClientRects().length &&
      boxesMeet(notice.el.getBoundingClientRect(), barRect)
    )
      offerToLine(notice);
  });
}
// A page verdict line's chip with no room to stand in (verdict/flow-line.ts placeLineChips) takes its undo to the
// status line.
function chipAway(chip) {
  NOTICES.forEach((notice) => {
    if (notice.el === chip && notice.place === NOTICE_PLACE.CHIP) offerToLine(notice);
  });
}
// Places every save chip on screen again by chipInRoom's rules, from its mark's or line's place now: after a zoom
// (setW) and, once a frame, while the PDF area scrolls either way - its place was set in px, so a zoomed page or a
// sideways scroll could leave [되돌리기] off the PDF area or under the panel or its handle.
function placeChips() {
  NOTICES.forEach((notice) => {
    const chip = notice.el,
      anchor = chip && chip.parentElement;
    if (notice.place !== NOTICE_PLACE.CHIP || !chip || !anchor || !chip.isConnected || anchor.classList.contains('pv'))
      return;
    chip.style.left = '';
    chip.style.right = '';
    chip.style.maxWidth = '';
    chipInRoom(chip, anchor);
  });
}
let CHIP_FRAME = 0;
$('#left').addEventListener(
  'scroll',
  () => {
    if (!CHIP_FRAME)
      CHIP_FRAME = requestAnimationFrame(() => {
        CHIP_FRAME = 0;
        placeChips();
        chipsClearOfBar();
      });
  },
  { passive: true },
);
// body.selmode comes and goes
new MutationObserver(chipsClearOfBar).observe(document.body, { attributes: true, attributeFilter: ['class'] });
// The list reload after a save or an append has run: a chip whose mark did not come goes to the status line
// (drawChips).
function settleChip(notice) {
  if (!notice || !NOTICES.has(notice.n) || notice.place !== NOTICE_PLACE.CHIP) return;
  notice.pending = false;
  drawChips();
}
// Moves an undo whose place left the screen to the status line, with the same action, what it holds (gone) and life; a
// TIMER one gets a window of its own there. A pressed one (busy: its request is out) does not move - it is offered
// nowhere else, and goes when the request is answered (noticeAct); the place it left was its own doing (a save's chip
// and its mark).
function offerToLine(notice) {
  if (notice.busy) return;
  const act = notice.act,
    gone = notice.gone;
  notice.gone = null;
  endNotice(notice, true);
  if (!act) return;
  // Its title and description stay as they were split: joined back with ' · ' a title that holds one ('#6 채택 판정
  // 저장됨 · PL16') was cut at it on the line.
  const moved = lineNote(notice.desc ? notice.title + ' — ' + notice.desc : notice.title, NOTICE_KIND.OK, act, {
    life: notice.life,
    gone,
    literal: true,
    undo: true,
    quiet: true,
  }); // said when it came: not again as it moves
  DEFERRED.forEach((send) => {
    if (send.note === notice) send.note = moved;
  });
} // an early send takes the moved undo away

// Trash rows: an undo in the place of the row it took away (after the row drawn before it, or first). drawTrash calls
// this.
function drawTrashOffers() {
  const box = $('#trash-list');
  NOTICES.forEach((notice) => {
    if (notice.place !== NOTICE_PLACE.TRASH) return;
    const element = noticeElement(notice, 'nt-row'),
      previous = notice.prev != null ? box.querySelector('.arc-row[data-id="' + notice.prev + '"]') : null;
    if (previous) previous.after(element);
    else box.prepend(element);
  });
}
// Closing the Trash takes its rows' undos to the status line: inside a closed dialog they could no longer be pressed.
$('#trash').addEventListener('close', () => {
  NOTICES.forEach((notice) => {
    if (notice.place === NOTICE_PLACE.TRASH) offerToLine(notice);
  });
});

// Deferred send with an undo (docs/handbook/viewer.md §알림 자리): commit runs when its undo leaves - after NOTICE_MS,
// on [x], or when the page is hidden - and [되돌리기] (cancel) runs undo instead, before anything reaches the server.
// So an agent never sees a reply or a permanent delete that was taken back. note = the undo drawn for it, which an
// early commit takes away. Its own bound is the guard: whatever holds or moves its undo, it is sent NOTICE_MS +
// NOTICE_HOLD_MAX after it was made at the latest. Runs once, cancels once, never both.
const DEFERRED = new Set();
function deferred(commit, undo) {
  let done = false;
  const bound = setTimeout(() => send.run(), NOTICE_MS + NOTICE_HOLD_MAX);
  const send = {
    note: null,
    run: () => {
      if (done) return;
      done = true;
      clearTimeout(bound);
      DEFERRED.delete(send);
      if (send.note) endNotice(send.note, true);
      commit();
    },
    cancel: () => {
      if (done) return;
      done = true;
      clearTimeout(bound);
      DEFERRED.delete(send);
      undo();
    },
  };
  DEFERRED.add(send);
  return send;
}
// Draws a deferred send's undo (undoNote, a TIMER life): its end sends, its [되돌리기] cancels. Returns it.
function deferredNote(send, place, message, options) {
  const notice = undoNote(
    place,
    message,
    { label: '되돌리기', tip: '보내기 전에 취소합니다', fn: send.cancel },
    { ...options, life: NOTICE_LIFE.TIMER, gone: send.run },
  );
  send.note = notice;
  return notice;
}
// The page is hidden or closed: what waits is sent now (fetch keepalive), and its undo goes - it could no longer
// cancel.
function flushDeferred() {
  Array.from(DEFERRED).forEach((send) => send.run());
}
window.addEventListener('pagehide', flushDeferred);
document.addEventListener('visibilitychange', () => {
  if (document.hidden) flushDeferred();
});

// ------------------------------------------------ Server calls
// Calls the server (JSON in and out) at endpoint, an ApiAnswers key (types/api.d.ts): its method, and its path with
// options.id in place of {id}, followed by options.query as the caller built it ('?a=1&doc=ms', withDocQuery). Returns
// {status, data}, data the endpoint's declared answer, or for a status options.expect lists the endpoint's ApiRefusals
// body (isRefusal tells the two apart); a network failure or an unexpected status >= 400 throws. Unless options.silent it is said first (apiFailed): options.what names the request ('핀 저장'), options.where
// the place (a NOTICE_HOST), options.retry the action a network failure offers, options.save that it was a pin's save.
// options.quietUnreached leaves a failure to reach the server to the caller to say (a refusal is still said).
// options.expect lists the statuses the caller handles itself; options.keepalive lets the request outlive the page;
// options.signal (an AbortSignal) ends it unanswered, as a network failure - also while its body is read. options.wait
// (ms) is the longest it waits for an answer, body included; past it the request is ended and is a network failure like
// any other (API_WAIT). Its error is keyed by its source - options.source, else its method and URL (which name its pin
// and document) with options.intent, what it asks of a URL several actions share (a pin's edit: 'edit', 'loc',
// 'append', 'append-undo'): a repeat replaces it, and an answer from the same source - the same intent - clears it
// (sourceOk). How long a request waits for an answer (ms). A server that cannot be reached does not always refuse: on a
// tailnet with no internet behind it the name still resolves and the request goes into the tunnel, and nothing comes
// back for as long as the system lets a connection wait - a minute and more. Everything that tells "cut off" from
// "connected" hangs on a request failing, so a request that only waited would leave the viewer connected and busy: the
// light poll would count no failure, a drag's composer would not open, a save would not end and nothing would reach the
// queue. A request that carries a wait is ended at it and fails as an unreached server does. POLL the light poll, and
// the question a send of the queue starts with READ a document read that has a stored answer to fall back on
// (offline/flow.ts OFF_READS) PICK finding a selection's lines SAVE writing a new pin SEND a request of the queue's
// send Requests without one (a rebuild, a revision's diff or build) may take as long as the server needs. API_OUT says
// the last request that ended got no answer (or the worker answered this page from its copy because the network did
// not, offlineAskDown). While it stands and a stored answer may serve (offlineMayServe), a document read with a stored
// answer is answered from it without asking: a visit's first reads are made one after another, and each waiting out its
// own request would draw the page a read's wait later, every time. The light poll always asks, and its answer - any
// answer - takes API_OUT down.
// The copies kept for reading while cut off (offline/flow.ts): a document read's key, whether a stored answer may
// serve, the stored answer, saying once how old it is, the connection back, keeping an answer. Platform knows no
// feature, so this is a seam: js/main.ts registers it once, before boot() runs (no code that runs while the script loads
// sends a request), and api() calls it at the point, with the arguments and in the order it calls the offline code. A
// request before the registration throws, naming the seam.
