    right = rect.left + (rect.width + pageWidth(widestPagePoints(), PAGE_SCALE)) / 2;
  const x =
    Math.round(
      Math.min(right + PANEL_GAP, areaRect.left + area.clientWidth - PANEL_WIDTH) - at.getBoundingClientRect().left,
    ) + 'px';
